import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] inputInts = getInputInts(sc);
        int n = inputInts[0];
        int m = inputInts[1];

        int edges_total = n * (n - 1) / 2;
        int[][][] dp_state = new int[n + 1][edges_total + 1][n + 1];
        dp_state[1][0][1] = 1;

        for (int i = 1; i < n; i++) {
            for (int j = 0; j <= edges_total; j++) {
                for (int k = 1; k <= n; k++) {
                    int val = dp_state[i][j][k];
                    if (val == 0) continue;
                    if (j + i <= edges_total && k + 1 <= n) {
                        dp_state[i + 1][j + i][k + 1] = (dp_state[i + 1][j + i][k + 1] + val) % m;
                    }
                    for (int l = 0; l < i; l++) {
                        int newJ = j + i - 1 - l;
                        if (newJ <= edges_total) {
                            dp_state[i + 1][newJ][k] = (dp_state[i + 1][newJ][k] + val) % m;
                        }
                    }
                }
            }
        }

        int[][][] sum_dp = new int[n + 1][n + 1][edges_total + 1];
        for (int i = 0; i <= n; i++) {
            for (int k = 0; k <= n; k++) {
                int total = 0;
                for (int j = 0; j <= edges_total; j++) {
                    total = (total + dp_state[i][j][k]) % m;
                    sum_dp[i][k][j] = total;
                }
            }
        }

        int[][][] cumulative_sum = new int[n + 1][edges_total + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= edges_total; j++) {
                int total = 0;
                for (int k = 0; k <= n; k++) {
                    total = (total + sum_dp[i][k][j]) % m;
                    cumulative_sum[i][j][k] = total;
                }
            }
        }

        int[] res_arr = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            long res = (long) i * res_arr[i - 1] % m;
            for (int k = 0; k <= n; k++) {
                for (int j = 1; j <= edges_total; j++) {
                    if (dp_state[i][j][k] == 0) continue;
                    int val = cumulative_sum[i][j - 1][n] - cumulative_sum[i][j - 1][k];
                    if (val < 0) val += m;
                    res = (res + (long) dp_state[i][j][k] * val) % m;
                }
            }
            res_arr[i] = (int) res;
        }

        System.out.println(res_arr[n]);
        sc.close();
    }

    private static int[] getInputInts(Scanner sc) {
        String[] parts = sc.nextLine().split(" ");
        int[] result = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            result[i] = Integer.parseInt(parts[i]);
        }
        return result;
    }
}
